\item OpenAI, \emph{The Solomon–Yau least-volume theorem}, 2026-09-23; citation key \texttt{OAI:The-Solomon-Yau-least-volume-theorem-September-23-2026}. \href{https://github.com/openai/math/blob/adc7f1241b42e322a6451854ab7e4b4c146bf78a/preprints/The-Solomon-Yau-least-volume-theorem-September-23-2026/paper.pdf}{PDF (GitHub)}; \href{https://github.com/openai/math/raw/adc7f1241b42e322a6451854ab7e4b4c146bf78a/preprints/The-Solomon-Yau-least-volume-theorem-September-23-2026/paper.pdf}{PDF (direct)}; \href{https://github.com/openai/math/blob/adc7f1241b42e322a6451854ab7e4b4c146bf78a/preprints/The-Solomon-Yau-least-volume-theorem-September-23-2026/README.md}{Manuscript page and citation}; \href{https://github.com/openai/math/blob/main/preprints/The-Solomon-Yau-least-volume-theorem-September-23-2026/paper.pdf}{Latest version}.
\item \href{https://github.com/openai/math/blob/adc7f1241b42e322a6451854ab7e4b4c146bf78a/CONTENTS.md}{OpenAI catalogue entry}.
